package org.example;

import java.io.FileOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;

public class Logging implements Loggable {

    private static final String LINE_SEPARATOR = System.lineSeparator();
    private static final String THREAD_NAME_KEY = "threadName";

    private volatile LogLevel currentLevel = LogLevel.TRACE;
    private Formatable formatter;
    private Context context;

    private PrintStream printer = System.out;
    private boolean ownsPrinter = false;

    public static Loggable getLogger(Formatable formatter, LogOptions options) {
        var logger = new Logging();
        logger.formatter = formatter;
        logger.setOptions(options);
        logger.context = new Context();
        logger.context.put(THREAD_NAME_KEY, Thread.currentThread().getName());
        return logger;
    }

    @Override
    public synchronized Loggable setCurrentLevel(LogLevel level) {
        this.currentLevel = level;
        return this;
    }

    @Override
    public synchronized Loggable setOptions(LogOptions options) {
        var newFormatter = options.getFormatter();
        if (newFormatter != null) {
            this.formatter = newFormatter;
        }

        var destination = options.getDestination();
        if (destination == null) {
            return this;
        }
        try {
            PrintStream next = switch (destination) {
                case LogDestination.Stdout ignored ->
                    System.out;
                case LogDestination.Stderr ignored ->
                    System.err;
                case LogDestination.LogFile logFile ->
                    new PrintStream(new FileOutputStream(logFile.path(), true), true);
            };
            if (this.ownsPrinter) {
                this.printer.close();
            }
            this.printer = next;
            this.ownsPrinter = destination instanceof LogDestination.LogFile;
        } catch (Exception e) {
            this.printer.println("Failed to set log destination: " + e.getMessage());
        }

        return this;
    }

    private void log(LogLevel level, String message) {
        if (level.severity() < this.currentLevel.severity()) {
            return;
        }
        write(LogEvent.create(message, level, System.currentTimeMillis()));
    }

    private synchronized void write(LogEvent logEvent) {
        try {
            var formattedMessage = this.formatter.getFormattedString(logEvent);
            this.printer.write((formattedMessage + LINE_SEPARATOR).getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            reportFormattingFailure(e);
        } finally {
            // TODO: Consider flushing only on certain levels or based on options and not on
            // every log call.
            this.printer.flush();
        }
    }

    private void reportFormattingFailure(Exception failure) {
        try {
            var event = LogEvent.create("Failed to format log message: " + failure.getMessage(), LogLevel.ERROR, System.currentTimeMillis());
            var formattedError = this.formatter.getFormattedString(event);
            this.printer.println(formattedError);
        } catch (Exception alsoFailed) {
            this.printer.println(LogLevel.color(LogLevel.ERROR)
                    + "Failed to format log message: " + failure.getMessage()
                    + LogLevel.color(LogLevel.RESET));
        }
    }

    @Override
    public void trace(String message) {
        log(LogLevel.TRACE, message);
    }

    @Override
    public void debug(String message) {
        log(LogLevel.DEBUG, message);
    }

    @Override
    public void info(String message) {
        log(LogLevel.INFO, message);
    }

    @Override
    public void warn(String message) {
        log(LogLevel.WARN, message);
    }

    @Override
    public void error(String message) {
        log(LogLevel.ERROR, message);
    }

    @Override
    public void fatal(String message) {
        log(LogLevel.FATAL, message);
    }
}
